// Photos, albums, videos and round videos in the message list (media slice 5a-1) against the mocked client's `media` scenario
// (chats "Mia Photos": 24 photos, "Vic Videos": 7 videos and 40 text messages, "Saved Messages": 3 photos; the assets are
// generated by scripts/mock/generateMediaAssets.ts and served, part by part, by `__invokeMiddlewares__/media.ts`).
// The gates remove `navigator.serviceWorker` (tests/e2e/fixtures.ts), so every media loads as a blob URL: the streaming path has
// its own spec, progressive.spec.ts.
import type { Page } from '@playwright/test';
import { statSync } from 'node:fs';

import { expect, test } from './fixtures';
import { LIST, MOCK_NOISE, openChat, openScenario, scrollListTo, settle, type TestWindow } from './middleHelpers';

test.use({ strictOptions: { ignoreConsole: MOCK_NOISE } });

const MIA = 'Mia Photos';
const VIC = 'Vic Videos';

// message ids of the scenario (scripts/mock/generateMediaScenario.ts): Mia's text is 1, the photo N of the spec list is N + 2
const ALBUM2 = [2, 3];
const HOSTILE = 4;
const WIDE = 5;
const TALL = 6;
const SPOILER = 7;
const SQUARE = 21; // photo 120: 640x640, with a caption, outgoing; near the bottom, so it is mounted when the chat opens
const ALBUM4 = [22, 23, 24, 25];

const ALBUM_LAYOUT_MODULE = '/src/components/middle/message/helpers/calculateAlbumLayout.ts';
const albumOf = (page: Page, which: 'first' | 'last') => page.locator(`${LIST} .Album`)[which]();
const message = (page: Page, id: number) => page.locator(`${LIST} .Message[data-message-id="${id}"]`);

async function openMia(page: Page) {
  await openScenario(page, 'media', 3);
  await openChat(page, MIA);
}

async function openVic(page: Page) {
  await openScenario(page, 'media', 3);
  await openChat(page, VIC);
}

// A field of the (first) tab's state, by path: `tabState(page, 'mediaViewer', 'messageId')`
async function tabState(page: Page, ...path: string[]): Promise<unknown> {
  return page.evaluate((keys) => {
    const { byTabId } = (window as unknown as TestWindow).getGlobal();
    let value: any = byTabId[Object.keys(byTabId)[0]];
    for (const key of keys) value = value?.[key];
    return value;
  }, path);
}

test.describe('photos', () => {
  test('a photo shows its blurred thumbnail first, then the full image, in a box that does not change', async ({
    page,
  }) => {
    // Record, from before the app starts, what the photo of message 9 (a 640x640 square) does while it loads.
    await page.addInitScript((id) => {
      const w = window as unknown as { __photo: Record<string, any> };
      w.__photo = { shifts: 0, events: [] };
      new PerformanceObserver((list) => {
        for (const entry of list.getEntries() as unknown as { value: number; sources?: { node?: Node }[] }[]) {
          if (
            entry.sources?.some(
              (source) => source.node && (source.node as Element).closest?.(`[data-message-id="${id}"] .media-inner`),
            )
          ) {
            w.__photo.shifts += entry.value;
          }
        }
      }).observe({ type: 'layout-shift', buffered: true });

      // (no layout read here: stricterdom would report a measurement outside a frame phase; the size comes from a ResizeObserver)
      let size = { width: 0, height: 0 };
      const observed = new WeakSet<Element>();
      const resizes = new ResizeObserver((entries) => {
        const box = entries[entries.length - 1].borderBoxSize[0];
        size = { width: Math.round(box.inlineSize), height: Math.round(box.blockSize) };
        sample('resize');
      });
      const sample = (what: string) => {
        const frame = document.querySelector(`#MiddleColumn .Message[data-message-id="${id}"] .media-inner`);
        if (!frame) return;
        if (!observed.has(frame)) {
          observed.add(frame);
          resizes.observe(frame);
        }
        const canvas = frame.querySelector<HTMLCanvasElement>('canvas.thumbnail:not(.blurred-bg)');
        const image = frame.querySelector<HTMLImageElement>('img.full-media');
        w.__photo.events.push({
          what,
          t: performance.now(),
          ...size,
          hasThumb: Boolean(canvas),
          thumbWidth: canvas?.width ?? 0,
          hasImage: Boolean(image),
          imageLoaded: Boolean(image?.complete && image.naturalWidth),
        });
      };
      new MutationObserver((records) => {
        for (const record of records) {
          const target = record.target as Element;
          if (target.closest?.(`.Message[data-message-id="${id}"]`)) {
            sample('mutation');
            return;
          }
        }
      }).observe(document, { subtree: true, childList: true, attributes: true });
    }, SQUARE);

    await openMia(page);
    await expect(message(page, SQUARE).locator('img.full-media')).toBeVisible();
    await expect
      .poll(() =>
        message(page, SQUARE)
          .locator('img.full-media')
          .evaluate((img: HTMLImageElement) => img.complete && img.naturalWidth),
      )
      .toBe(640);

    const { events, shifts } = await page.evaluate(() => (window as unknown as { __photo: any }).__photo);
    const frames = events.filter((event: any) => event.width > 0);
    const firstThumb = frames.findIndex((event: any) => event.hasThumb);
    const firstImage = frames.findIndex((event: any) => event.hasImage);
    expect(firstThumb, 'the thumbnail canvas is created').toBeGreaterThanOrEqual(0);
    expect(firstImage, 'the image is created').toBeGreaterThanOrEqual(0);
    expect(firstThumb, 'the thumbnail is there no later than the image').toBeLessThanOrEqual(firstImage);
    // the stripped thumbnail (40 px) was handed to the worker: the canvas has its size
    expect(Math.max(...frames.map((event: any) => event.thumbWidth))).toBe(40);

    // no reflow: the box is the same from the first frame to the last (a layout shift of the photo is a missing dimension)
    const widths = new Set(frames.map((event: any) => event.width));
    const heights = new Set(frames.map((event: any) => event.height));
    expect(widths.size, `widths ${[...widths].join(',')}`).toBe(1);
    expect(heights.size, `heights ${[...heights].join(',')}`).toBe(1);
    expect(shifts).toBe(0);
  });

  test('the box of a 20000x10 photo and of a 10:1 and a 1:10 one is clamped', async ({ page }) => {
    await openMia(page);
    await scrollListTo(page, 'top');
    await settle(page);

    for (const id of [HOSTILE, WIDE, TALL]) {
      const frame = message(page, id).locator('.media-inner');
      await frame.scrollIntoViewIfNeeded();
      const { width, height, ratio, style } = await frame.evaluate((el: HTMLElement) => {
        const rect = el.getBoundingClientRect();
        return {
          width: rect.width,
          height: rect.height,
          ratio: el.style.getPropertyValue('--media-aspect-ratio'),
          style: el.getAttribute('style') ?? '',
        };
      });
      expect(Number.isFinite(width) && Number.isFinite(height), `${id} finite box`).toBe(true);
      expect(height, `${id} height`).toBeLessThanOrEqual(27 * 16 + 1);
      expect(width, `${id} width`).toBeLessThanOrEqual(30 * 16);
      expect(style).not.toMatch(/NaN|Infinity/);
      expect(Number(ratio), `${id} ratio`).toBeGreaterThanOrEqual(0.1);
      expect(Number(ratio), `${id} ratio`).toBeLessThanOrEqual(10);
    }
  });

  test('a spoiler photo is covered until it is clicked', async ({ page }) => {
    await openMia(page);
    await scrollListTo(page, 'top');
    await settle(page);

    const frame = message(page, SPOILER).locator('.media-inner');
    await frame.scrollIntoViewIfNeeded();
    const spoiler = frame.locator('.media-spoiler');
    await expect(spoiler).toBeVisible();
    await frame.click();
    await expect(spoiler).toBeHidden();
    // the second click opens the viewer (tab state; the viewer itself is the next slice)
    await frame.click();
    await expect.poll(() => tabState(page, 'mediaViewer', 'messageId')).toBe(SPOILER);
  });

  test('a click on a photo opens the media viewer (tab state) for that message', async ({ page }) => {
    await openMia(page);
    const frame = message(page, SQUARE).locator('.media-inner');
    await frame.scrollIntoViewIfNeeded();
    await expect(frame.locator('img.full-media')).toBeVisible();
    await frame.click();
    await expect.poll(() => tabState(page, 'mediaViewer', 'messageId')).toBe(SQUARE);
    expect(await tabState(page, 'mediaViewer', 'chatId')).toBe('21');
  });
});

test.describe('albums', () => {
  const RATIOS: Record<string, number[]> = {
    '2': [800 / 600, 600 / 800],
    '4': [800 / 600, 600 / 800, 640 / 640, 960 / 540],
  };

  async function albumRects(page: Page, which: 'first' | 'last') {
    const album = albumOf(page, which);
    await album.scrollIntoViewIfNeeded();
    return album.evaluate((el: HTMLElement) => {
      const box = el.getBoundingClientRect();
      return {
        box: { width: box.width, height: box.height },
        ratio: el.style.getPropertyValue('--album-aspect-ratio'),
        items: [...el.children].map((child) => {
          const rect = child.getBoundingClientRect();
          return {
            x: (rect.left - box.left) / box.width,
            y: (rect.top - box.top) / box.height,
            w: rect.width / box.width,
            h: rect.height / box.height,
          };
        }),
      };
    });
  }

  for (const [label, ids] of [
    ['2', ALBUM2],
    ['4', ALBUM4],
  ] as const) {
    test(`an album of ${label} lays its items out as calculateAlbumLayout says, without overlap`, async ({ page }) => {
      await openMia(page);
      if (label === '2') {
        await scrollListTo(page, 'top');
        await settle(page);
      }
      // the album is one message element holding all parts: its id is the main message's
      const { items, ratio } = await albumRects(page, label === '2' ? 'first' : 'last');
      // the app's own layout function, from the module the dev server serves (importing it here would pull the whole API type graph
      // into the typecheck of the scripts)
      const layout = await page.evaluate(
        async ([module, ratios]) => {
          const { calculateAlbumLayout } = await import(/* @vite-ignore */ module);
          return calculateAlbumLayout(ratios) as {
            aspectRatio: number;
            items: { rect: { x: number; y: number; width: number; height: number } }[];
          };
        },
        [ALBUM_LAYOUT_MODULE, RATIOS[label]] as const,
      );

      expect(items).toHaveLength(ids.length);
      expect(Number(ratio)).toBeCloseTo(layout.aspectRatio, 3);
      items.forEach((item, index) => {
        const expected = layout.items[index].rect;
        expect(item.x).toBeCloseTo(expected.x, 2);
        expect(item.y).toBeCloseTo(expected.y, 2);
        expect(item.w).toBeCloseTo(expected.width, 2);
        expect(item.h).toBeCloseTo(expected.height, 2);
      });
      for (let a = 0; a < items.length; a++) {
        for (let b = a + 1; b < items.length; b++) {
          const overlapX =
            Math.min(items[a].x + items[a].w, items[b].x + items[b].w) - Math.max(items[a].x, items[b].x);
          const overlapY =
            Math.min(items[a].y + items[a].h, items[b].y + items[b].h) - Math.max(items[a].y, items[b].y);
          expect(overlapX > 0.001 && overlapY > 0.001, `items ${a} and ${b} overlap`).toBe(false);
        }
      }
    });
  }

  test('every part of an album loads its image and a click opens the viewer on that part', async ({ page }) => {
    await openMia(page);
    const album = albumOf(page, 'last');
    await album.scrollIntoViewIfNeeded();
    await expect(album.locator('img.full-media')).toHaveCount(4);
    await expect
      .poll(() =>
        album
          .locator('img.full-media')
          .evaluateAll((images: HTMLImageElement[]) => images.map((img) => img.naturalWidth)),
      )
      .toEqual([800, 600, 640, 960]);

    await album.locator('.media-inner').nth(2).click();
    await expect.poll(() => tabState(page, 'mediaViewer', 'messageId')).toBe(ALBUM4[2]);
  });
});

test.describe('videos', () => {
  const VIDEO = 1;
  const GIF = 2;
  const ROUND = 3;
  const BIG = 6;
  const ROUND_2 = 7;
  const playing = (page: Page, id: number) =>
    message(page, id)
      .locator('video')
      .first()
      .evaluate((video: HTMLVideoElement) => !video.paused && !video.ended);
  const time = (page: Page, id: number) =>
    message(page, id)
      .locator('video')
      .first()
      .evaluate((video: HTMLVideoElement) => video.currentTime);

  test('an autoplay video plays while it is on screen, pauses when it is scrolled away and plays again when it is back', async ({
    page,
  }) => {
    await openVic(page);
    await scrollListTo(page, 'top');
    await settle(page);

    await expect.poll(() => playing(page, VIDEO)).toBe(true);
    const t0 = await time(page, VIDEO);
    await expect.poll(() => time(page, VIDEO)).not.toBe(t0);

    // scrolled away (the 40 text messages are below): the video is removed from the playing set at once
    await scrollListTo(page, 'bottom');
    await expect.poll(() => playing(page, VIDEO), { timeout: 2000 }).toBe(false);
    // (the element is still there or gone: either way nothing plays off screen)
    await expect
      .poll(() =>
        page
          .locator(`${LIST} video`)
          .evaluateAll((videos: HTMLVideoElement[]) => videos.filter((v) => !v.paused).length),
      )
      .toBe(0);

    await scrollListTo(page, 'top');
    await expect.poll(() => playing(page, VIDEO)).toBe(true);
  });

  test('a GIF autoplays with the GIF badge and the video has its duration badge', async ({ page }) => {
    await openVic(page);
    await scrollListTo(page, 'top');
    await settle(page);

    await expect(message(page, GIF).locator('.message-media-duration')).toHaveText('GIF');
    await expect.poll(() => playing(page, GIF)).toBe(true);
    await expect(message(page, VIDEO).locator('.message-media-duration')).toContainText(/0:0[0-2]/);
  });

  test('the box of a video is the declared size before and after it loads', async ({ page }) => {
    await openVic(page);
    await scrollListTo(page, 'top');
    await settle(page);
    const frame = message(page, VIDEO).locator('.media-inner');
    await expect(frame.locator('video')).toBeVisible();
    const box = await frame.evaluate((el: HTMLElement) => ({
      ratio: Number(el.style.getPropertyValue('--media-aspect-ratio')),
      rect: el.getBoundingClientRect().toJSON(),
    }));
    expect(box.ratio).toBeCloseTo(640 / 360, 3);
    expect(box.rect.width / box.rect.height).toBeCloseTo(640 / 360, 1);
  });

  test('a big video (more than three download parts) loads whole through the chunked GetFile', async ({ page }) => {
    await openVic(page);
    await scrollListTo(page, 'top');
    await settle(page);
    await message(page, BIG).scrollIntoViewIfNeeded();
    const video = message(page, BIG).locator('video');
    await expect.poll(() => video.evaluate((el: HTMLVideoElement) => el.readyState)).toBeGreaterThanOrEqual(3);
    const { size, duration, width } = await video.evaluate(async (el: HTMLVideoElement) => ({
      size: (await (await fetch(el.currentSrc)).blob()).size,
      duration: el.duration,
      width: el.videoWidth,
    }));
    expect(size).toBe(statSync('src/lib/gramjs/client/__data__/media/video-206.webm').size);
    expect(duration).toBeCloseTo(3, 0);
    expect(width).toBe(640);
  });

  test('with autoplay off a video shows the play button and does not play', async ({ page }) => {
    await openScenario(page, 'media', 3);
    await page.evaluate(() => {
      (window as unknown as TestWindow).getActions().updatePerformanceSettings({ autoplayVideos: false });
    });
    await openChat(page, VIC);
    await scrollListTo(page, 'top');
    await settle(page);

    const frame = message(page, VIDEO).locator('.media-inner');
    await expect(frame.locator('video')).toBeVisible();
    await expect(frame.locator('.icon-play')).toBeVisible();
    await page.waitForTimeout(500);
    expect(await playing(page, VIDEO)).toBe(false);
  });

  test('leaving the chat releases every video element', async ({ page }) => {
    await openVic(page);
    await scrollListTo(page, 'top');
    await settle(page);
    await expect.poll(() => page.locator('video').count()).toBeGreaterThan(0);

    await page.keyboard.press('Escape');
    await page.locator(LIST).waitFor({ state: 'detached' });
    await expect.poll(() => page.locator('video').count()).toBe(0);
  });

  test('a click on a video opens the media viewer (tab state) for that message', async ({ page }) => {
    await openVic(page);
    await scrollListTo(page, 'top');
    await settle(page);
    await message(page, VIDEO).locator('.media-inner').click();
    await expect.poll(() => tabState(page, 'mediaViewer', 'messageId')).toBe(VIDEO);
  });
  // Stopping a round video pauses a video whose own `play()` is still settling; tt's `safePlay` logs that AbortError (DEBUG builds).
  test.describe('round videos', () => {
    test.use({
      strictOptions: { ignoreConsole: [...MOCK_NOISE, /The play\(\) request was interrupted by a call to pause\(\)/] },
    });

    test('a round video plays with sound on click and starting another one stops the first', async ({ page }) => {
      await openVic(page);
      await scrollListTo(page, 'top');
      await settle(page);

      const roundVideo = (id: number) => message(page, id).locator('.RoundVideo');
      await roundVideo(ROUND).scrollIntoViewIfNeeded();
      await expect(roundVideo(ROUND).locator('video')).toBeVisible();
      const state = (id: number) =>
        roundVideo(id)
          .locator('video')
          .evaluate((video: HTMLVideoElement) => ({ paused: video.paused, muted: video.muted }));

      await roundVideo(ROUND).click();
      await expect.poll(() => state(ROUND)).toEqual({ paused: false, muted: false });

      await roundVideo(ROUND_2).scrollIntoViewIfNeeded();
      await roundVideo(ROUND_2).click();
      await expect.poll(() => state(ROUND_2)).toEqual({ paused: false, muted: false });
      await expect.poll(async () => (await state(ROUND)).muted).toBe(true);
    });
  });
});

test.describe('downloads', () => {
  test('a download goes through the DownloadManager: the file is saved under the sanitised name', async ({ page }) => {
    await openVic(page);

    const download = page.waitForEvent('download');
    await page.evaluate(() => {
      const { getGlobal, getActions } = window as unknown as TestWindow;
      const global = getGlobal();
      const originMessage = global.messages.byChatId['22'].byId[5];
      const media = { ...originMessage.content.video, fileName: 'evil‮exe.txt' };
      getActions().downloadMedia({ media, originMessage });
    });
    const file = await download;
    // the bidi override that would make `evil` + `txt.exe` out of the name is gone
    expect(file.suggestedFilename()).toBe('evilexe.txt');
    const path = await file.path();
    expect(path).toBeTruthy();
    expect(statSync(path).size).toBe(statSync('src/lib/gramjs/client/__data__/media/video-205.webm').size);
    // the record is removed from the tab state when the manager is done with it
    await expect
      .poll(() => tabState(page, 'activeDownloads').then((record) => Object.keys(record as object).length))
      .toBe(0);
  });
});

test.describe('the message list around media', () => {
  test('a photo that arrives while the list is scrolled up keeps the anchor', async ({ page }) => {
    await openMia(page);
    await page.mouse.move(800, 400);
    await page.mouse.wheel(0, -900);
    await settle(page);

    const anchor = () =>
      page.evaluate(() => {
        const list = document.querySelector('#MiddleColumn .MessageList') as HTMLElement;
        const top = list.getBoundingClientRect().top;
        const item = [...list.querySelectorAll<HTMLElement>('.message-list-item')].find(
          (el) => el.getBoundingClientRect().bottom > top + 40,
        )!;
        return { id: item.dataset.messageId, top: Math.round(item.getBoundingClientRect().top - top) };
      });
    const before = await anchor();

    await page.evaluate(() => {
      (window as unknown as TestWindow).getActions().apiUpdate({
        '@type': 'newMessage',
        chatId: '21',
        id: 500,
        message: {
          id: 500,
          chatId: '21',
          date: Math.floor(Date.now() / 1000),
          isOutgoing: false,
          senderId: '21',
          content: {
            photo: { mediaType: 'photo', id: '101', date: 1, sizes: [{ type: 'x', width: 800, height: 600 }] },
          },
        },
      });
    });
    await expect(page.locator(`${LIST} #message-500`)).toHaveCount(1);
    await settle(page);

    expect(await anchor()).toEqual(before);
  });

  // R5 of the plan: the load of a photo is a state machine over several effects (allowed, intersecting, fetch, resolved); it must
  // not park under a heavy animation. The left column slide (the main menu -> Settings) is one; the chat is opened while it runs.
  // (Saved Messages itself cannot be opened through the menu under the mock: it has no `currentUserId`.)
  test('a chat opened during a heavy animation (the left column slide) loads its photos', async ({ page }) => {
    await openScenario(page, 'media', 3);
    await page.locator('#LeftMainHeader .DropdownMenu button').first().click();
    await page.getByRole('menuitem', { name: 'Settings' }).click();

    // the slide starts when the menu has closed
    await page.waitForFunction(() => document.querySelector('#LeftColumn .Transition_slide-from'), undefined, {
      polling: 'raf',
    });
    const sliding = await page.evaluate(() => {
      (window as unknown as TestWindow).getActions().openChat({ id: '1' });
      return document.querySelectorAll('#LeftColumn .Transition_slide-from, #LeftColumn .Transition_slide-to').length;
    });
    expect(sliding, 'the left column is sliding when the chat is opened').toBeGreaterThan(0);

    await expect(page.locator('#MiddleColumn .MiddleHeader')).toContainText(/Saved ?Messages/);
    await expect(page.locator(`${LIST} img.full-media`)).toHaveCount(3);
    await expect
      .poll(() =>
        page
          .locator(`${LIST} img.full-media`)
          .evaluateAll((images: HTMLImageElement[]) => images.every((img) => img.naturalWidth > 0)),
      )
      .toBe(true);
  });
});
